<?php
/**
 * install_race_results_menu_v001_20260727_022317pm.php
 *
 * VERSION: v001
 * LAST MODIFIED: 7/27/2026 2:23:17 pm
 *
 * CHANGELOG:
 * v001 (7/27/2026 2:23:17 pm)
 * - Initial one-time installer for race_results_menu.php.
 * - Installs into the same race_results folder as this installer.
 * - Creates a timestamped backup when race_results_menu.php already exists.
 * - Verifies the written file contents after installation.
 */

date_default_timezone_set('America/New_York');

$targetFile = __DIR__ . '/race_results_menu.php';
$targetDisplay = 'race_results_menu.php';
$backupFile = '';
$errors = array();
$messages = array();

$payload = <<<'MRL_BASE64_PAYLOAD'

MRL_BASE64_PAYLOAD;

$decoded = base64_decode($payload, true);

if ($decoded === false) {
    $errors[] = 'The embedded race_results_menu.php payload could not be decoded.';
}

if (empty($errors) && file_exists($targetFile)) {
    $backupFile = __DIR__ . '/race_results_menu_backup_' . date('Ymd_His') . '.php';

    if (!@copy($targetFile, $backupFile)) {
        $errors[] = 'The existing race_results_menu.php could not be backed up.';
    } else {
        $messages[] = 'Existing file backed up as ' . basename($backupFile) . '.';
    }
}

if (empty($errors)) {
    $bytesWritten = @file_put_contents($targetFile, $decoded, LOCK_EX);

    if ($bytesWritten === false) {
        $errors[] = 'The installer could not write race_results_menu.php.';
    } else {
        $messages[] = 'Installed race_results_menu.php (' . number_format($bytesWritten) . ' bytes).';
    }
}

if (empty($errors)) {
    $writtenContents = @file_get_contents($targetFile);

    if ($writtenContents === false) {
        $errors[] = 'The installed file could not be read back for verification.';
    } elseif (hash('sha256', $writtenContents) !== hash('sha256', $decoded)) {
        $errors[] = 'Verification failed: the installed file does not match the embedded payload.';
    } else {
        $messages[] = 'Verification passed.';
    }
}

$success = empty($errors);
?>
